# owner: platform
"""Seating charts: students sorted by last name, in rows."""

from rosterkit.errors import ProjectError


def _sort_key(student):
    return (student.last_name, student.first_name)


def _line(number, group):
    names = " | ".join(item.display_name for item in group)
    return f"Row {number}: {names}"


# ---
def seat_rows(students, seats):
    if seats < 1 or not students:
        raise ProjectError("need students and seats")
    ordered = sorted(students, key=_sort_key)
    starts = range(0, len(ordered), seats)
    groups = [ordered[base:base + seats] for base in starts]
    return [_line(*pair) for pair in enumerate(groups, 1)]

